// Formats the weekly report.
const CHAT_ID = 'YOUR_CHAT_ID';
const r = $input.first().json;
const n = v => Number(v ?? 0);
const pct = (a, b) => (n(b) ? Math.round(100 * n(a) / n(b)) + '%' : '—');
const filters = (r.top_filters ?? []).map(f => `   • ${f.reason}: ${f.n}`).join('\n') || '   • none';

const text = [
  `📊 Weekly report — Job Copilot`,
  ``,
  `🔎 Found: ${n(r.found)} (JSearch ${n(r.from_jsearch)} · LinkedIn ${n(r.from_linkedin)})`,
  `🚫 Filtered: ${n(r.rule_filtered)} by rules · ${n(r.ai_filtered)} by AI`,
  `⭐ Scored: ${n(r.scored)} (avg score ${r.avg_score ?? '—'})`,
  `📄 CVs tailored: ${n(r.tailored)}`,
  `✅ Approved: ${n(r.approved)} · ❌ Skipped: ${n(r.skipped)}`,
  `📨 Applied: ${n(r.applied)}`,
  `🎤 Interviews: ${n(r.interviews)} · 🙅 Rejections: ${n(r.rejections)} · 🎉 Offers: ${n(r.offers)}`,
  ``,
  `📈 All time: ${n(r.applied_total)} applications · response rate ${pct(r.answered_total, r.applied_total)} · interview rate ${pct(r.interviews_total, r.applied_total)}`,
  ``,
  `Top filter reasons this week:`,
  filters,
  ``,
  n(r.found) === 0 ? `⚠️ No new jobs this week: check the sourcing workflows and your API quota.` :
  n(r.approved) === 0 && n(r.tailored) > 0 ? `💡 You approved nothing this week. Is the score threshold too low?` : `Keep going, Here your name! 💪`,
].join('\n');

return [{ json: { chat_id: CHAT_ID, text } }];

// Formats follow-up reminders (one message for all of them).
const CHAT_ID = 'YOUR_CHAT_ID';
const rows = $input.all().map(i => i.json).filter(r => r.id);
const applied = rows.filter(r => r.status === 'applied');
const approved = rows.filter(r => r.status === 'approved');

const lines = [`⏰ Follow-ups`];
if (applied.length) {
  lines.push('', `📨 Applied, no answer yet:`);
  for (const r of applied) lines.push(`• Job ${r.id}: ${r.title} — ${r.company} (${r.days} days)`);
  lines.push(`💡 A short follow-up message to the recruiter on LinkedIn can help. Tell me "job X was rejected" or "job X: interview" when you hear back.`);
}
if (approved.length) {
  lines.push('', `✅ Approved but not marked as applied:`);
  for (const r of approved) lines.push(`• Job ${r.id}: ${r.title} — ${r.company} (${r.days} days)\n  ${r.url}`);
  lines.push(`💡 Applied already? Tell me "mark job X as applied". Not interested anymore? "skip job X".`);
}

return [{ json: { chat_id: CHAT_ID, text: lines.join('\n').slice(0, 4000), ids: rows.map(r => r.id) } }];

